import subprocess
import time
import threading
def task_func(file_list):
    exit_codes = [None] * len(file_list)

    def run_file(filepath, index):
        try:
            result = subprocess.run([filepath], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            exit_codes[index] = result.returncode
        except Exception:
            exit_codes[index] = -1

    threads = []
    for i, file in enumerate(file_list):
        t = threading.Thread(target=run_file, args=(file, i))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    return exit_codes

