import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")

    system = platform.system()
    end_time = time.time() + duration
    logs = []

    while time.time() < end_time:
        cpu_percent = 0.0
        try:
            if system == 'Windows':
                output = subprocess.check_output(['wmic', 'cpu', 'get', 'loadpercentage'])
                for line in output.decode().split('\n'):
                    if line.strip() and not line.startswith('LoadPercentage'):
                        cpu_percent = float(line.strip())
                        break
            else:
                output = subprocess.check_output(['top', '-bn1'])
                for line in output.decode().split('\n'):
                    if 'Cpu(s)' in line:
                        cpu_part = line.split(':')[1].split(',')[0].strip()
                        cpu_percent = float(cpu_part.replace('%us', '').replace('%', ''))
                        break
        except Exception:
            cpu_percent = 0.0

        logs.append({'timestamp': time.time(), 'cpu_usage': cpu_percent})
        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(logs, f)
        return LOGFILE_PATH
    except IOError:
        return None

