import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")

    process = subprocess.Popen(['bash', script_path])
    try:
        ps_process = psutil.Process(process.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    cpu_total = 0.0
    mem_total = 0
    last_rss = 0
    start_time = time.time()

    while process.poll() is None:
        if time.time() - start_time > timeout:
            process.terminate()
            process.wait()
            break

        try:
            cpu = ps_process.cpu_percent(interval=0.1)
            mem_info = ps_process.memory_info()
            current_rss = mem_info.rss

            if current_rss > last_rss:
                mem_total += current_rss - last_rss

            last_rss = current_rss
            cpu_total += cpu
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            break

    return {'CPU Usage': cpu_total, 'Memory Usage': mem_total}

